// build-sdk.mjs — bundle src/sdk.ts (base class + contract helper + zod) into a generated TS
// module the host injects as `processor.js` into userspace processor isolates. Single source of
// truth: the SAME core/processor.ts the host runs is what userspace extends. Run by the test
// and deploy scripts; the generated file is committed so typecheck works without a build.
import { build } from "esbuild";
import { writeFileSync } from "node:fs";

const sdk = await build({
  entryPoints: ["src/sdk.ts"],
  bundle: true,
  format: "esm",
  platform: "neutral",
  target: "es2022",
  minify: true,
  write: false,
});
writeFileSync(
  "src/generated/processor-sdk.ts",
  "// GENERATED by build-sdk.mjs from src/sdk.ts — do not edit.\n" +
    `export const PROCESSOR_SDK_MODULE = ${JSON.stringify(sdk.outputFiles[0].text)};\n`,
);
console.log(`processor.js: ${(sdk.outputFiles[0].text.length / 1024).toFixed(1)} KiB`);

// The runner: REAL TypeScript (src/runner-entry.ts) — cap.js/processor.js/cloudflare:workers
// stay external (they exist only inside the loaded isolate).
const runner = await build({
  entryPoints: ["src/runner-entry.ts"],
  bundle: true,
  format: "esm",
  platform: "neutral",
  target: "es2022",
  minify: true,
  write: false,
  external: ["cloudflare:workers", "./cap.js", "./processor.js"],
});
writeFileSync(
  "src/generated/processor-runner.ts",
  "// GENERATED by build-sdk.mjs from src/runner-entry.ts — do not edit.\n" +
    `export const PROCESSOR_RUNNER_MODULE = ${JSON.stringify(runner.outputFiles[0].text)};\n`,
);
console.log(`runner.js: ${(runner.outputFiles[0].text.length / 1024).toFixed(1)} KiB`);
